import _codecs
f = _codecs.readbuffer_encode
for args in [(), (b'', None, None), (None,), (b'', True), (b'', '\0'), (b'A', None), ('é', None)]:
    try:
        print('result', repr(f(*args)))
    except BaseException as error:
        print(type(error).__name__, repr(error.args))
try:
    f(b'', errors='strict')
except BaseException as error:
    print(type(error).__name__, repr(error.args))

